using ApiGateway.Middleware;
using ApiGateway.Services.Auth;
using ApiGateway.Services.Proxy;
using ApiGateway.Services.Tracing;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

var builder = WebApplication.CreateBuilder(args);

// Configure services
builder.Services.AddControllers();

// Configure JWT Authentication
builder.Services.AddAuthentication(options =>
{
    options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
    options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
})
.AddJwtBearer(options =>
{
    options.TokenValidationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidateAudience = true,
        ValidateLifetime = true,
        ValidateIssuerSigningKey = true,
        ValidIssuer = builder.Configuration["Jwt:Issuer"],
        ValidAudience = builder.Configuration["Jwt:Audience"],
        IssuerSigningKey = new SymmetricSecurityKey(
            Convert.FromBase64String(builder.Configuration["Jwt:Key"]))
    };

    options.Events = new JwtBearerEvents
    {
        OnAuthenticationFailed = context =>
        {
            if (context.Exception.GetType() == typeof(SecurityTokenExpiredException))
            {
                context.Response.Headers.Add("WWW-Authenticate", "Bearer error=\"expired_token\"");
            }
            return Task.CompletedTask;
        }
    };
});

// Add Reverse Proxy Forwarder
builder.Services.AddReverseProxy()
    .LoadFromConfig(builder.Configuration.GetSection("ReverseProxy"));

// Add JWT Authorization
builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("AdminOnly", policy => policy.RequireClaim("scope", "admin"));
    options.AddPolicy("UserOnly", policy => policy.RequireClaim("scope", "user"));
});

// Add Distributed Tracing
builder.Services.AddOpenTelemetry()
    .WithTracing(tracerProviderBuilder =>
    {
        tracerProviderBuilder
            .AddAspNetCoreInstrumentation()
            .AddHttpClientInstrumentation()
            .AddOtlpExporter(options =>
            {
                options.Endpoint = new Uri(builder.Configuration["Tracing:Endpoint"]);
            })
            .SetResourceBuilder(ResourceBuilder.CreateDefault()
                .AddService(serviceName: builder.Configuration["Tracing:ServiceName"]));
    });

// Add custom services
builder.Services.AddSingleton<IAuthService, AuthService>();
builder.Services.AddSingleton<IProxyService, ProxyService>();
builder.Services.AddSingleton<ITracingService, TracingService>();

// Add middleware
builder.Services.AddHttpContextAccessor();
builder.Services.AddSingleton<ITracingMiddleware, TracingMiddleware>();

var app = builder.Build();

// Configure the HTTP request pipeline
app.UseRouting();

// Add tracing middleware first
app.UseMiddleware<TracingMiddleware>();

// Add authentication and authorization
app.UseAuthentication();
app.UseAuthorization();

// Add reverse proxy
app.MapReverseProxy();

// Add health checks
app.MapHealthChecks("/health");

app.Run();
```

#### Middleware/TracingMiddleware.cs

```csharp
using ApiGateway.Services.Tracing;
using Microsoft.AspNetCore.Http;

public class TracingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ITracingService _tracingService;

    public TracingMiddleware(RequestDelegate next, ITracingService tracingService)
    {
        _next = next;
        _tracingService = tracingService;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Generate or extract correlation ID
        var correlationId = _tracingService.GetOrCreateCorrelationId(context);

        // Add correlation ID to headers
        context.Request.Headers.Add("X-Correlation-ID", correlationId);

        // Add correlation ID to tracing context
        _tracingService.SetCorrelationIdInTracingContext(correlationId);

        // Call the next middleware in the pipeline
        await _next(context);
    }
}
