#### Services/Proxy/ProxyService.cs

```csharp
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Http;
using Microsoft.Extensions.Options;
using Microsoft.Net.Http.Headers;
using Microsoft.ReverseProxy;
using Microsoft.ReverseProxy.Models;

public interface IProxyService
{
    Task<ProxyRequest> CreateProxyRequestAsync(HttpContext context);
}

public class ProxyService : IProxyService
{
    private readonly IConfiguration _configuration;
    private readonly IHttpClientFactory _httpClientFactory;

    public ProxyService(IConfiguration configuration, IHttpClientFactory httpClientFactory)
    {
        _configuration = configuration;
        _httpClientFactory = httpClientFactory;
    }

    public async Task<ProxyRequest> CreateProxyRequestAsync(HttpContext context)
    {
        var route = _configuration["ReverseProxy:Routes"]
            .Split(';')
            .FirstOrDefault(r => r.StartsWith(context.Request.Path.Value));

        if (string.IsNullOrEmpty(route))
            return null;

        var routeConfig = route.Split(':');
        var serviceName = routeConfig[0];
        var path = routeConfig[1];

        var request = new ProxyRequest
        {
            RouteKey = serviceName,
            DestinationHost = new DestinationHost
            {
                Address = _configuration[$"ReverseProxy:Services:{serviceName}:Url"]
            },
            RequestMessage = new ProxyRequestMessage(context.Request)
            {
                Headers = new ProxyHeaders(context.Request.Headers)
            }
        };

        // Forward original path
        request.RequestMessage.Path = new PathString(path);

        // Forward query parameters
        request.RequestMessage.QueryString = new QueryString(context.Request.QueryString.Value);

        // Forward headers (except those we don't want to forward)
        var headersToForward = new[]
        {
            HeaderNames.Host,
            HeaderNames.UserAgent,
            HeaderNames.Accept,
            HeaderNames.ContentType,
            HeaderNames.Authorization,
            HeaderNames.XCorrelationId
        };

        foreach (var header in headersToForward)
        {
            if (context.Request.Headers.TryGetValue(header, out var values))
            {
                request.RequestMessage.Headers[header] = values;
            }
        }

        return request;
    }
}
```

#### Services/Tracing/TracingService.cs

```csharp
using Microsoft.AspNetCore.Http;
using OpenTelemetry;
using OpenTelemetry.Trace;

public interface ITracingService
{
    string GetOrCreateCorrelationId(HttpContext context);
    void SetCorrelationIdInTracingContext(string correlationId);
}

public class TracingService : ITracingService
{
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly TracerProvider _tracerProvider;

    public TracingService(IHttpContextAccessor httpContextAccessor, TracerProvider tracerProvider)
    {
        _httpContextAccessor = httpContextAccessor;
        _tracerProvider = tracerProvider;
    }

    public string GetOrCreateCorrelationId(HttpContext context)
    {
        // Try to get existing correlation ID from headers
        if (context.Request.Headers.TryGetValue("X-Correlation-ID", out var correlationId))
        {
            return correlationId;
        }

        // Generate a new one if none exists
        return Guid.NewGuid().ToString();
    }

    public void SetCorrelationIdInTracingContext(string correlationId)
    {
        var activity = _tracerProvider.TracerProvider.GetCurrentActivity();
        if (activity != null)
        {
            activity.SetTag("correlation.id", correlationId);
        }
    }
}
